dtsPropsFor.GuideStayHome:
lodging: {
    id: string; name: string; city: string; tagline: string;
    /** URL de la photo principale du logement (hero de la page Séjour). */
    coverImage: string; gallery: string[];
    latitude: number; longitude: number; addressLabel: string;
    /** Heures « HH:MM », ex. "16:00" / "10:00". */
    checkIn: string; checkOut: string;
    wifiName: string; wifiPassword: string;
    /** URL YouTube de la vidéo de présentation (optionnelle). */
    presentationVideoUrl?: string;
    arrivalInstructions: {
      title?: string | null; text: string; videoUrl: string | null;
      /** 1re photo = image principale de l'étape ; 5 médias max (photos + vidéo). */
      photos: string[];
      /** "access" affiche le code de boîte à clés masqué ; "address" l'adresse + Maps. */
      kind: "address" | "access" | "garage" | "ski" | "custom";
      tip: string | null;
      substeps: { title: string; detail: string }[];
      facts: { label: string; value: string }[];
    }[];
    departureInstructions: string[];
    houseRules: string[];
    /** Équipements ; icon = slug Lucide kebab-case, "recycle" = tri des déchets. */
    practicalCards: { id: string; title: string; description: string; icon: string; phone?: string; photoUrl?: string; videoUrl?: string }[];
    usefulNumbers: { label: string; number: string }[];
    trashBins: { type: string }[];
    trashLocation: string | null;
    keyBoxCode: string | null;
    stats: { guests: number | null; bedrooms: number | null; surfaceM2: number | null };
    /** true si latitude/longitude viennent de l'adresse géocodée (sinon : centre-ville). */
    locationPrecise: boolean;
    facilibus: boolean;
    transportCards: { id: string; title: string; tag: string | null; body: string }[];
  };
  /** Coups de cœur du carrousel (Urgences et Mobilité y sont masqués). */
  pois: {
    id: string; name: string;
    category: { slug: string; name: string; icon: string; color: string };
    /** URL de photos ; la 1re sert d'image de carte. */
    photos: string[];
    latitude: number; longitude: number;
    /** Statut d'ouverture ; absent = pas de badge. */
    isOpenNow?: boolean;
    /** Libellé de distance/temps affiché en bas de carte, ex. "6 min" ou "350 m". */
    distanceLabel?: string;
    /** Icône du libellé : marcheur, voiture ou repère (vol d'oiseau). */
    distanceMode?: "walking" | "driving" | "crow";
    durationLabel?: string;
    /** Temps MapBox depuis le logement (secondes). */
    travel?: { walkingSeconds: number | null; drivingSeconds: number | null };
  }[];
  /** Nombre de tâches de départ cochées (tuile « Départ »). */
  departureDone: number;
  onNavigate: (view: "arrival" | "rules" | "departure" | "favorites") => void;
  onOpenWifi: () => void;
  onOpenPoi: (poi: {
    id: string; name: string;
    category: { slug: string; name: string; icon: string; color: string };
    /** URL de photos ; la 1re sert d'image de carte. */
    photos: string[];
    latitude: number; longitude: number;
    /** Statut d'ouverture ; absent = pas de badge. */
    isOpenNow?: boolean;
    /** Libellé de distance/temps affiché en bas de carte, ex. "6 min" ou "350 m". */
    distanceLabel?: string;
    /** Icône du libellé : marcheur, voiture ou repère (vol d'oiseau). */
    distanceMode?: "walking" | "driving" | "crow";
    durationLabel?: string;
    /** Temps MapBox depuis le logement (secondes). */
    travel?: { walkingSeconds: number | null; drivingSeconds: number | null };
  }) => void;
  onShowPoiOnMap?: (poi: {
    id: string; name: string;
    category: { slug: string; name: string; icon: string; color: string };
    /** URL de photos ; la 1re sert d'image de carte. */
    photos: string[];
    latitude: number; longitude: number;
    /** Statut d'ouverture ; absent = pas de badge. */
    isOpenNow?: boolean;
    /** Libellé de distance/temps affiché en bas de carte, ex. "6 min" ou "350 m". */
    distanceLabel?: string;
    /** Icône du libellé : marcheur, voiture ou repère (vol d'oiseau). */
    distanceMode?: "walking" | "driving" | "crow";
    durationLabel?: string;
    /** Temps MapBox depuis le logement (secondes). */
    travel?: { walkingSeconds: number | null; drivingSeconds: number | null };
  }) => void;
  /** Temps de trajet par id de lieu (secondes). */
  travelTimes?: Record<string, { walkingSeconds: number | null; drivingSeconds: number | null }> | null;
  /** Nœud affiché sous les tuiles, typiquement <GuideTransportRow />. */
  transportEntry?: React.ReactNode;

